  --content "FUNCTION_BLOCK ArmControl
VAR_INPUT
    ManualMode : BOOL;
    SingleStepMode : BOOL;
    SingleCycleMode : BOOL;
    ContinuousMode : BOOL;
    EmergencyStop : BOOL;
    Start : BOOL;
    DownButton : BOOL;
    UpButton : BOOL;
    LeftButton : BOOL;
    RightButton : BOOL;
    GripButton : BOOL;
    ReleaseButton : BOOL;
    DownLimitSwitch : BOOL;
    UpLimitSwitch : BOOL;
    LeftLimitSwitch : BOOL;
    RightLimitSwitch : BOOL;
    GripLimitSwitch : BOOL;
    ReleaseLimitSwitch : BOOL;
END_VAR
VAR_OUTPUT
    MoveDown : BOOL;
    MoveUp : BOOL;
    MoveLeft : BOOL;
    MoveRight : BOOL;
    ActivateGrip : BOOL;
    ActivateRelease : BOOL;
END_VAR
VAR
    step : INT := 0;
    prevStart : BOOL := FALSE;
    startRisingEdge : BOOL := FALSE;
    gripActive : BOOL := FALSE;
    releaseActive : BOOL := FALSE;
END_VAR

// Detect rising edge of Start button
startRisingEdge := Start AND NOT prevStart;
prevStart := Start;

// Emergency stop: reset everything when triggered
IF NOT EmergencyStop THEN
    MoveDown := FALSE;
    MoveUp := FALSE;
    MoveLeft := FALSE;
    MoveRight := FALSE;
    ActivateGrip := FALSE;
    ActivateRelease := FALSE;
    step := 0;
    gripActive := FALSE;
    releaseActive := FALSE;
    RETURN;
END_IF

// Mode selection logic
IF ManualMode THEN
    // Manual Mode: Individual control of each action
    MoveDown := DownButton AND (NOT DownLimitSwitch);
    MoveUp := UpButton AND (NOT UpLimitSwitch);
    MoveLeft := LeftButton AND (NOT LeftLimitSwitch);
    MoveRight := RightButton AND (NOT RightLimitSwitch);
    ActivateGrip := GripButton AND gripActive;
    ActivateRelease := ReleaseButton AND releaseActive;

    // Reset other mode states
    step := 0;

ELSSEIF SingleStepMode THEN
    // Single Step Mode: One action per start button press
    // Reset manual outputs
    MoveDown := FALSE;
    MoveUp := FALSE;
    MoveLeft := FALSE;
    MoveRight := FALSE;
    ActivateGrip := FALSE;
    ActivateRelease := FALSE;

    IF startRisingEdge THEN
        // Execute step based on current step number
        CASE step OF
            0: // Move down
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    MoveDown := FALSE;
                    step := 1;
                END_IF

            1: // Grip
                ActivateGrip := TRUE;
                IF GripLimitSwitch THEN
                    ActivateGrip := FALSE;
                    gripActive := TRUE;
                    step := 2;
                END_IF

            2: // Move up
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    MoveUp := FALSE;
                    step := 3;
                END_IF

            3: // Move right
                MoveRight := TRUE;
                IF RightLimitSwitch THEN
                    MoveRight := FALSE;
                    step := 4;
                END_IF

            4: // Move down
                MoveDown := TRUE;
                IF DownLimitSwitch THEN
                    MoveDown := FALSE;
                    step := 5;
                END_IF

            5: // Release
                ActivateRelease := TRUE;
                IF ReleaseLimitSwitch THEN
                    ActivateRelease := FALSE;
                    releaseActive := FALSE;
                    step := 6;
                END_IF

            6: // Move up
                MoveUp := TRUE;
                IF UpLimitSwitch THEN
                    MoveUp := FALSE;
                    step := 7;
                END_IF

            7: // Move left
                MoveLeft := TRUE;
                IF LeftLimitSwitch THEN
                    MoveLeft := FALSE;
                    step := 0; // Cycle back to beginning
                END_IF
        END_CASE
    END_IF

    // Check if current action is completed (for non-start press cases)
    IF NOT startRisingEdge THEN
        CASE step OF
            0:
                IF DownLimitSwitch THEN
                    MoveDown := FALSE;
                END_IF

            1:
                IF GripLimitSwitch THEN
                    ActivateGrip := FALSE;
                    gripActive := TRUE;
                END_IF

            2:
                IF UpLimitSwitch THEN
                    MoveUp := FALSE;
                END_IF

            3:
                IF RightLimitSwitch THEN
                    MoveRight := FALSE;
                END_IF

            4:
                IF DownLimitSwitch THEN
                    MoveDown := FALSE;
                END_IF

            5:
                IF ReleaseLimitSwitch THEN
                    ActivateRelease := FALSE;
                    releaseActive := FALSE;
                END_IF

            6:
                IF UpLimitSwitch THEN
                    MoveUp := FALSE;
                END_IF

            7:
                IF LeftLimitSwitch THEN
                    MoveLeft := FALSE;
                END_IF
        END_CASE
    END_IF

ELSSEIF SingleCycleMode THEN
    // Single Cycle Mode: Complete cycle and stop
    MoveDown := FALSE;
    MoveUp := FALSE;
    MoveLeft := FALSE;
    MoveRight := FALSE;
    ActivateGrip := FALSE;
    ActivateRelease := FALSE;

    // Start cycle on first start press
    IF startRisingEdge AND step = 0 THEN
        step := 1;
    END_IF

    // Execute cycle steps
    CASE step OF
        1: // Move down
            MoveDown := TRUE;
            IF DownLimitSwitch THEN
                MoveDown := FALSE;
                step := 2;
            END_IF

        2: // Grip
            ActivateGrip := TRUE;
            IF GripLimitSwitch THEN
                ActivateGrip := FALSE;
                gripActive := TRUE;
                step := 3;
            END_IF

        3: // Move up
            MoveUp := TRUE;
            IF UpLimitSwitch THEN
                MoveUp := FALSE;
                step := 4;
            END_IF

        4: // Move right
            MoveRight := TRUE;
            IF RightLimitSwitch THEN
                MoveRight := FALSE;
                step := 5;
            END_IF

        5: // Move down
            MoveDown := TRUE;
            IF DownLimitSwitch THEN
                MoveDown := FALSE;
                step := 6;
            END_IF

        6: // Release
            ActivateRelease := TRUE;
            IF ReleaseLimitSwitch THEN
                ActivateRelease := FALSE;
                releaseActive := FALSE;
                step := 7;
            END_IF

        7: // Move up
            MoveUp := TRUE;
            IF UpLimitSwitch THEN
                MoveUp := FALSE;
                step := 8;
            END_IF

        8: // Move left
            MoveLeft := TRUE;
            IF LeftLimitSwitch THEN
                MoveLeft := FALSE;
                step := 0; // Stop at end of cycle
                gripActive := FALSE;
            END_IF
    END_CASE

ELSSEIF ContinuousMode THEN
    // Continuous Mode: Keep executing cycle
    MoveDown := FALSE;
    MoveUp := FALSE;
    MoveLeft := FALSE;
    MoveRight := FALSE;
    ActivateGrip := FALSE;
    ActivateRelease := FALSE;

    // Start cycle on first start press
    IF startRisingEdge AND step = 0 THEN
        step := 1;
    END_IF

    // Execute cycle steps continuously
    CASE step OF
        1: // Move down
            MoveDown := TRUE;
            IF DownLimitSwitch THEN
                MoveDown := FALSE;
                step := 2;
            END_IF

        2: // Grip
            ActivateGrip := TRUE;
            IF GripLimitSwitch THEN
                ActivateGrip := FALSE;
                gripActive := TRUE;
                step := 3;
            END_IF

        3: // Move up
            MoveUp := TRUE;
            IF UpLimitSwitch THEN
                MoveUp := FALSE;
                step := 4;
            END_IF

        4: // Move right
            MoveRight := TRUE;
            IF RightLimitSwitch THEN
                MoveRight := FALSE;
                step := 5;
            END_IF

        5: // Move down
            MoveDown := TRUE;
            IF DownLimitSwitch THEN
                MoveDown := FALSE;
                step := 6;
            END_IF

        6: // Release
            ActivateRelease := TRUE;
            IF ReleaseLimitSwitch THEN
                ActivateRelease := FALSE;
                releaseActive := FALSE;
                step := 7;
            END_IF

        7: // Move up
            MoveUp := TRUE;
            IF UpLimitSwitch THEN
                MoveUp := FALSE;
                step := 8;
            END_IF

        8: // Move left
            MoveLeft := TRUE;
            IF LeftLimitSwitch THEN
                MoveLeft := FALSE;
                step := 1; // Cycle back to step 1 (continuous)
            END_IF
    END_CASE

ELSE
    // No mode selected or invalid state
    MoveDown := FALSE;
    MoveUp := FALSE;
    MoveLeft := FALSE;
    MoveRight := FALSE;
    ActivateGrip := FALSE;
    ActivateRelease := FALSE;
    step := 0;
    gripActive := FALSE;
    releaseActive := FALSE;
END_IF

END_FUNCTION_BLOCK
"
